 public static string Install(){if(EditorApplication.isPlaying)throw new Exception("Stop Play first");if(UnityEngine.SceneManagement.SceneManager.GetActiveScene().isDirty)throw new Exception("Save scene before applying visual family");ArtKit.Ensure();
 string raider="Assets/RoadGunner/Prefabs/Wasteland Raider.prefab",buggy="Assets/RoadGunner/Prefabs/Rust Vulture Enemy Buggy.prefab",pickup="Assets/RoadGunner/Prefabs/Scrap pickup.prefab";
 var sources=new string[3];sources[0]=raider;sources[1]=ArtKit.Root+"/Prefabs/Wasteland Enforcer.prefab";sources[2]=ArtKit.Root+"/Prefabs/Wasteland Veteran.prefab";
 for(int variant=0;variant<3;variant++){int v=variant;var p=PrefabUtility.LoadPrefabContents(raider);try{ConceptEnemies.ApplyRaider(p.GetComponent<Raider>(),v);PrefabUtility.SaveAsPrefabAsset(p,sources[v]);}finally{PrefabUtility.UnloadPrefabContents(p);}}
 Prefab(buggy,g=>ConceptEnemies.ApplyBuggy(g.GetComponent<EnemyBuggy>()));Prefab(pickup,ConceptEnemies.ApplyPickup);
 string folder="Assets/RoadGunner/Levels/WastelandRestored/Prefabs";foreach(string path in Directory.GetFiles(folder,"*.prefab")){string kind=Path.GetFileNameWithoutExtension(path);Prefab(path,g=>ConceptEnvironment.ApplyProp(g,kind));}
 Prefab("Assets/RoadGunner/Levels/Greenwood/Prefabs/Cliff.prefab",g=>ConceptEnvironment.ApplyProp(g,"Cliff"));
 foreach(string kind in new[]{"Cactus","Wooden supply crate","Boulder"}){var g=new GameObject(kind);try{ConceptEnvironment.ApplyProp(g,kind);foreach(var c in g.GetComponentsInChildren<Collider>())Object.DestroyImmediate(c);PrefabUtility.SaveAsPrefabAsset(g,ArtKit.Root+"/Prefabs/"+kind+".prefab");}finally{Object.DestroyImmediate(g);}}
 AssetDatabase.SaveAssets();EditorSceneManager.OpenScene(ScenePath);var l=RoadGunnerLevelAuthoring.Current;var s=l.session;var d=s.spawns;
 var oldRaiders=d.pool.Concat(d.authoredRaiders).Where(r=>r).Distinct().ToArray();var replacements=new Dictionary<Raider,Raider>();int index=0;foreach(var old in oldRaiders){int variant=old.tuning.enemyHealth>=220?2:old.tuning.enemyHealth>=100?1:index%5==2?1:0;var g=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(sources[variant]),old.transform.parent);g.name=old.name;g.transform.SetPositionAndRotation(old.transform.position,old.transform.rotation);g.transform.localScale=old.transform.localScale;var r=g.GetComponent<Raider>();r.session=s;r.tuning=old.tuning;g.SetActive(old.gameObject.activeSelf);Record(r);Record(g.transform);replacements[old]=r;index++;}
 d.pool=d.pool.Where(r=>r).Select(r=>replacements[r]).ToArray();d.authoredRaiders=d.authoredRaiders.Where(r=>r).Select(r=>replacements[r]).ToArray();foreach(var old in oldRaiders)Object.DestroyImmediate(old.gameObject);
 var oldBuggies=d.buggyPool.Concat(d.authoredBuggies??Array.Empty<EnemyBuggy>()).Where(b=>b).Distinct().ToArray();var buggyMap=new Dictionary<EnemyBuggy,EnemyBuggy>();foreach(var old in oldBuggies){var g=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(buggy),old.transform.parent);g.name=old.name;g.transform.SetPositionAndRotation(old.transform.position,old.transform.rotation);g.transform.localScale=old.transform.localScale;var b=g.GetComponent<EnemyBuggy>();b.session=s;b.tuning=old.tuning;g.SetActive(old.gameObject.activeSelf);Record(b);Record(g.transform);buggyMap[old]=b;}d.buggyPool=d.buggyPool.Where(b=>b).Select(b=>buggyMap[b]).ToArray();d.authoredBuggies=(d.authoredBuggies??Array.Empty<EnemyBuggy>()).Where(b=>b).Select(b=>buggyMap[b]).ToArray();foreach(var old in oldBuggies)Object.DestroyImmediate(old.gameObject);
 for(int i=0;i<s.pickups.items.Length;i++){var old=s.pickups.items[i];var g=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(pickup),old.parent);g.name=old.name;g.transform.SetPositionAndRotation(old.position,old.rotation);g.transform.localScale=old.localScale;g.SetActive(old.gameObject.activeSelf);s.pickups.items[i]=g.transform;s.pickups.gearVisuals[i]=g.transform.Find("Metal gear");s.pickups.scrapVisuals[i]=g.transform.Find("Scrap plates");Record(g.transform);Object.DestroyImmediate(old.gameObject);}Record(d);Record(s.pickups);
 s.health.bodyPanels=s.vehicle.GetComponentsInChildren<Renderer>(true).Where(r=>r.name=="Finished shared visuals"&&r.transform.parent.name.Contains("Body and open cargo bed")).ToArray();Record(s.health);
