 static Texture2D SandTexture(){string path=ArtKit.Root+"/Textures/Quiet ochre sand.png";int n=256;var tex=new Texture2D(n,n,TextureFormat.RGBA32,true);var pixels=new Color[n*n];for(int y=0;y<n;y++)for(int x=0;x<n;x++){float u=x/(float)n,v=y/(float)n;float broad=Mathf.Sin(u*Mathf.PI*2+Mathf.Sin(v*Mathf.PI*2)*.8f)*Mathf.Cos(v*Mathf.PI*2)*.065f;float patch=Mathf.Sin((u+v)*Mathf.PI*6+Mathf.Sin(u*Mathf.PI*4))*.018f;float f=.965f+broad+patch;pixels[y*n+x]=new Color(f,f*.996f,f*.987f,1);}tex.SetPixels(pixels);tex.Apply();File.WriteAllBytes(path,tex.EncodeToPNG());Object.DestroyImmediate(tex);AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceSynchronousImport);var imp=(TextureImporter)AssetImporter.GetAtPath(path);imp.wrapMode=TextureWrapMode.Repeat;imp.filterMode=FilterMode.Bilinear;imp.maxTextureSize=256;imp.mipmapEnabled=true;imp.anisoLevel=2;imp.SaveAndReimport();return AssetDatabase.LoadAssetAtPath<Texture2D>(path);}
 static void Terrain(LevelLayout l){var tex=SandTexture();foreach(var key in new[]{"Sand","SandLight","SandShade","Track"}){var m=ArtKit.Mat(key);m.SetTexture("_BaseMap",tex);m.SetTextureScale("_BaseMap",new Vector2(.7f,.7f));EditorUtility.SetDirty(m);}var track=ArtKit.Mat("Track");track.SetColor("_BaseColor",ArtKit.Color("FD9D58"));
 l.ground.GetComponent<Renderer>().sharedMaterial=ArtKit.Mat("Sand");foreach(var r in l.decorationRoot.Find("00 · Routes and clear ground").GetComponentsInChildren<Renderer>()){var names=r.sharedMaterials.Select(m=>m?m.name:"").ToArray();r.sharedMaterials=names.Select(n=>n=="Track"?ArtKit.Mat("Track"):ArtKit.Mat("SandLight")).ToArray();}
 // Retire the old repeated sand ripple and green biome overrides on authored mesh-only surfaces.
 var mapped=new Dictionary<string,string>{{"Sand","Sand"},{"Dust","SandShade"},{"Track","Track"},{"Rock","RockShade"},{"RockLight","RockLight"},{"Concrete","IvoryShade"},{"Rust","Rust"},{"Metal","Steel"},{"Edge","SteelLight"},{"Cream","Ivory"},{"Warning","Ivory"},{"Teal","TealDark"},{"Red","Red"},{"Rubber","Rubber"}};
 foreach(var r in l.authoredContentRoot.GetComponentsInChildren<Renderer>(true)){if(r.sharedMaterials.Any(m=>m&&AssetDatabase.GetAssetPath(m).StartsWith(ArtKit.Root)))continue;var mats=r.sharedMaterials.Select(m=>m&&mapped.TryGetValue(m.name,out string key)?ArtKit.Mat(key):m).ToArray();r.sharedMaterials=mats;Record(r);}Record(l.ground.GetComponent<Renderer>());ConceptTerrainSurface.Apply(l);}
 static void Dressing(LevelLayout l){var old=l.decorationRoot.Find("Concept roadside accents");if(old)return;var root=ArtKit.Node("Concept roadside accents",l.decorationRoot).transform;var q=Quaternion.Euler(0,45,0);var items=new[]{new Vector2(-7,-34),new Vector2(8,-22),new Vector2(-10,6),new Vector2(-18,28),new Vector2(7,43),new Vector2(-7,49),new Vector2(26,16),new Vector2(-26,-25),new Vector2(33,28),new Vector2(-17,47)};for(int i=0;i<items.Length;i++){var at=q*new Vector3(items[i].x*2.5f,0,items[i].y*2.5f);foreach(var spec in new[]{("Cactus",new Vector3(-3,0,-1)),("Wooden supply crate",new Vector3(1.2f,0,2.3f)),("Boulder",new Vector3(3.0f,0,.7f))}){var g=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(ArtKit.Root+"/Prefabs/"+spec.Item1+".prefab"),root);g.transform.SetPositionAndRotation(at+q*spec.Item2,q*Quaternion.Euler(0,i*39,0));Record(g.transform);}}
 }
 static void SetSerialized(SerializedObject so,string name,float value){var p=so.FindProperty(name);if(p==null)return;if((p.propertyType==SerializedPropertyType.Integer||p.propertyType==SerializedPropertyType.Enum))p.intValue=Mathf.RoundToInt(value);else if(p.propertyType==SerializedPropertyType.Boolean)p.boolValue=value>.5f;else p.floatValue=value;}
 public static void Lighting(){var preset=AssetDatabase.LoadAssetAtPath<WastelandVisualPreset>(ArtKit.Root+"/Presets/Wasteland Visual Preset.asset");if(!preset){preset=ScriptableObject.CreateInstance<WastelandVisualPreset>();AssetDatabase.CreateAsset(preset,ArtKit.Root+"/Presets/Wasteland Visual Preset.asset");}preset.sharedMaterials=AssetDatabase.FindAssets("t:Material",new[]{ArtKit.Root+"/Materials"}).Select(id=>AssetDatabase.LoadAssetAtPath<Material>(AssetDatabase.GUIDToAssetPath(id))).ToArray();EditorUtility.SetDirty(preset);
 var lights=RoadGunnerLevelAuthoring.InScene<Light>();foreach(var light in lights){if(light.name.Contains("Sun")){light.transform.rotation=Quaternion.Euler(preset.sunlightEuler);RenderSettings.sun=light;light.color=ArtKit.Color("FFFAF3");light.intensity=preset.sunlightIntensity;light.shadows=LightShadows.Soft;light.shadowStrength=preset.shadowStrength;light.shadowBias=.045f;light.shadowNormalBias=.15f;light.GetUniversalAdditionalLightData().usePipelineSettings=false;}else if(light.type==LightType.Directional){light.intensity=.16f;light.transform.rotation=Quaternion.Euler(38,145,0);light.color=ArtKit.Color("CCD9EA");light.shadows=LightShadows.None;}Record(light);}
 RenderSettings.ambientMode=AmbientMode.Trilight;RenderSettings.ambientSkyColor=ArtKit.Color("858B90");RenderSettings.ambientEquatorColor=ArtKit.Color("787166");RenderSettings.ambientGroundColor=ArtKit.Color("584E40");RenderSettings.ambientIntensity=1;RenderSettings.fog=false;
 string vp=ArtKit.Root+"/Presets/Concept Warm Daylight.asset";var profile=AssetDatabase.LoadAssetAtPath<VolumeProfile>(vp);if(!profile){profile=ScriptableObject.CreateInstance<VolumeProfile>();AssetDatabase.CreateAsset(profile,vp);}profile.components.RemoveAll(c=>!c);if(!profile.TryGet<ColorAdjustments>(out var color)){color=profile.Add<ColorAdjustments>(true);AssetDatabase.AddObjectToAsset(color,profile);}color.postExposure.Override(0);color.contrast.Override(2);color.saturation.Override(0);color.colorFilter.Override(Color.white);if(!profile.TryGet<Tonemapping>(out var tone)){tone=profile.Add<Tonemapping>(true);AssetDatabase.AddObjectToAsset(tone,profile);}tone.mode.Override(TonemappingMode.None);EditorUtility.SetDirty(profile);EditorUtility.SetDirty(color);EditorUtility.SetDirty(tone);
 foreach(var volume in RoadGunnerLevelAuthoring.InScene<Volume>()){volume.sharedProfile=profile;volume.enabled=true;volume.isGlobal=true;volume.priority=10;volume.weight=1;Record(volume);}foreach(string path in new[]{"Assets/Settings/PC_RPAsset.asset","Assets/Settings/Mobile_RPAsset.asset"}){var rp=AssetDatabase.LoadAssetAtPath<UniversalRenderPipelineAsset>(path);if(!rp)continue;var so=new SerializedObject(rp);SetSerialized(so,"m_MSAA",2);SetSerialized(so,"m_RenderScale",1);SetSerialized(so,"m_MainLightShadowmapResolution",2048);SetSerialized(so,"m_MainLightShadowsSupported",1);SetSerialized(so,"m_ShadowNormalBias",.15f);SetSerialized(so,"m_ShadowDepthBias",.045f);SetSerialized(so,"m_SoftShadowsSupported",1);SetSerialized(so,"m_ShadowDistance",60);SetSerialized(so,"m_ShadowCascadeCount",2);SetSerialized(so,"m_SoftShadowQuality",1);so.ApplyModifiedPropertiesWithoutUndo();EditorUtility.SetDirty(rp);}AssetDatabase.SaveAssets();}
 public static void Hud(GameSession s){var neutral=NeutralPanel();foreach(var text in s.hud.GetComponentsInParent<Canvas>()[0].GetComponentsInChildren<Text>(true)){text.color=text.name.Contains("label")||text.name.Contains("hint")?ArtKit.Color("BFB698"):ArtKit.Color("ECE3CE");if(text.name=="Wordmark")text.text="ROAD GUNNER";if(text.name=="Repairing indicator")text.color=ArtKit.Color("85D6AD");if(text.name=="Sector")text.color=ArtKit.Color("8BB6AE");Record(text);}foreach(var image in s.hud.GetComponentInParent<Canvas>().GetComponentsInChildren<Image>(true)){if(image.sprite&&image.sprite.name.IndexOf("panel",StringComparison.OrdinalIgnoreCase)>=0)image.sprite=neutral;if(image==s.hud.healthFill)image.color=ArtKit.Color("85D6AD");else if(image.name.Contains("Knob"))image.color=new Color(.84f,.81f,.71f,.65f);else if(image.name.Contains("Joystick"))image.color=new Color(.19f,.28f,.28f,.27f);else if(image.GetComponent<Button>())image.color=ArtKit.Color("315E60");else if(image.name.Contains("fill")||image.name.Contains("Fill"))image.color=ArtKit.Color("397C7B");else image.color=new Color(.04f,.075f,.08f,image.color.a<.1f?image.color.a:.99f);if(image.name.Contains("Pause "))image.color=ArtKit.Color("D8CFB6");Record(image);}var repair=Object.FindAnyObjectByType<RepairWorkshop>();if(repair&&repair.repairingLabel)repair.repairingLabel.color=ArtKit.Color("85D6AD");}
 static Sprite NeutralPanel(){string path=ArtKit.Root+"/Textures/Neutral HUD panel.png";const int n=64;var t=new Texture2D(n,n,TextureFormat.RGBA32,false);for(int y=0;y<n;y++)for(int x=0;x<n;x++){float dx=Mathf.Max(0,10-Mathf.Min(x,n-1-x)),dy=Mathf.Max(0,10-Mathf.Min(y,n-1-y));float a=1-Mathf.Clamp01(Mathf.Sqrt(dx*dx+dy*dy)-9);t.SetPixel(x,y,new Color(1,1,1,a));}t.Apply();File.WriteAllBytes(path,t.EncodeToPNG());Object.DestroyImmediate(t);AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceSynchronousImport);var imp=(TextureImporter)AssetImporter.GetAtPath(path);imp.textureType=TextureImporterType.Sprite;imp.spriteImportMode=SpriteImportMode.Single;imp.spriteBorder=new Vector4(12,12,12,12);imp.alphaIsTransparency=true;imp.mipmapEnabled=false;imp.SaveAndReimport();return AssetDatabase.LoadAssetAtPath<Sprite>(path);}
 public static void Effects(GameSession s){var range=s.vehicle.GetComponent<AttackRangeIndicator>();if(range&&range.material){var m=new Material(range.material);m.name="Subtle ivory attack range";m.SetColor("_BaseColor",new Color(.84f,.80f,.66f,.27f));string path=ArtKit.Root+"/Materials/Attack Range.mat";var old=AssetDatabase.LoadAssetAtPath<Material>(path);if(old){EditorUtility.CopySerialized(m,old);Object.DestroyImmediate(m);m=old;}else AssetDatabase.CreateAsset(m,path);range.material=m;Record(range);}
 foreach(var ps in RoadGunnerLevelAuthoring.InScene<ParticleSystem>()){var main=ps.main;var emission=ps.emission;bool dust=ps.name.IndexOf("dust",StringComparison.OrdinalIgnoreCase)>=0;bool smoke=ps.name.IndexOf("smoke",StringComparison.OrdinalIgnoreCase)>=0;bool fire=ps.name.IndexOf("fire",StringComparison.OrdinalIgnoreCase)>=0;if(dust){main.startColor=new ParticleSystem.MinMaxGradient(new Color(.70f,.58f,.39f,.18f),new Color(.83f,.71f,.49f,.31f));main.maxParticles=Mathf.Min(main.maxParticles,100);main.startLifetime=new ParticleSystem.MinMaxCurve(.35f,.7f);main.startSize=new ParticleSystem.MinMaxCurve(.25f,.6f);}else if(smoke){main.startColor=new ParticleSystem.MinMaxGradient(new Color(.18f,.19f,.18f,.45f),new Color(.37f,.32f,.25f,.22f));main.maxParticles=Mathf.Min(main.maxParticles,60);}else if(fire)main.startColor=new ParticleSystem.MinMaxGradient(ArtKit.Color("FFC56B"),ArtKit.Color("C8753D"));Record(ps);}foreach(var t in s.effects.tracers){t.startWidth=.045f;t.endWidth=.024f;Record(t);}foreach(var t in s.effects.sparks){t.localScale=Vector3.one*.18f;Record(t);}var tracks=Object.FindAnyObjectByType<TireTracks>();if(tracks&&tracks.material){var m=new Material(tracks.material);m.name="Restrained sand tire imprints";m.SetColor("_BaseColor",new Color(.67f,.48f,.29f,.45f));string path=ArtKit.Root+"/Materials/Tire Imprints.mat";var old=AssetDatabase.LoadAssetAtPath<Material>(path);if(old){EditorUtility.CopySerialized(m,old);Object.DestroyImmediate(m);m=old;}else AssetDatabase.CreateAsset(m,path);tracks.material=m;Record(tracks);}}
